import{_ as o,o as r,c as n,ag as s}from"./chunks/framework.KxDd3USm.js";const u=JSON.parse('{"title":"03.7 项目管理基础 ★","description":"","frontmatter":{},"headers":[],"relativePath":"03-软件工程基础/07-项目管理基础.md","filePath":"03-软件工程基础/07-项目管理基础.md"}'),g={name:"03-软件工程基础/07-项目管理基础.md"};function a(d,t,e,p,h,l){return r(),n("div",null,[...t[0]||(t[0]=[s(`<h1 id="_03-7-项目管理基础-★" tabindex="-1">03.7 项目管理基础 ★ <a class="header-anchor" href="#_03-7-项目管理基础-★" aria-label="Permalink to &quot;03.7 项目管理基础 ★&quot;">​</a></h1><p>项目管理在选择题里考三块：<strong>进度（甘特 / PERT）、成本（COCOMO）、风险（风险暴露）</strong>，外加沟通路径这么一个小公式。</p><h3 id="_7-1-进度管理-甘特图与-pert-图-优缺点不能互串" tabindex="-1">7.1 进度管理：甘特图与 PERT 图（优缺点不能互串） <a class="header-anchor" href="#_7-1-进度管理-甘特图与-pert-图-优缺点不能互串" aria-label="Permalink to &quot;7.1 进度管理：甘特图与 PERT 图（优缺点不能互串）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>图</th><th>长什么样</th><th>优点</th><th>缺点</th></tr></thead><tbody><tr><td><strong>甘特图（Gantt）</strong></td><td>横轴时间、横条表示每个任务的起止与工期</td><td>清晰描述各任务<strong>从何时开始到何时结束</strong>、进程情况、以及<strong>任务间的并行关系</strong></td><td><strong>不能清晰反映各任务之间的依赖关系</strong>，难以确定整个项目的<strong>关键所在</strong></td></tr><tr><td><strong>PERT 图（网络图）</strong></td><td>结点 + 带权有向弧（结点表示里程碑，弧表示活动与其工期）</td><td>能清晰反映各任务之间的<strong>依赖关系</strong>，从而确定<strong>整个项目的关键所在</strong></td><td><strong>不能反映任务之间的并行关系</strong></td></tr></tbody></table><p><strong>这是一对&quot;互缺&quot;的图</strong>：甘特有&quot;并行&quot;没&quot;依赖&quot;，PERT 有&quot;依赖&quot;没&quot;并行&quot;。<strong>题干问到哪一句，就答缺哪一句</strong>——两个形容词一换就是错项。</p><p><strong>关键路径</strong>：从开始到结束<strong>需要时间最长</strong>的那条路径；<strong>项目工期 = 完成项目的最少时间，由关键路径决定</strong>。</p><p><strong>活动松弛时间（总时差）</strong>：在不延误总工期的前提下该活动的机动时间。它有<strong>两种算法、结果相同</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>总时差 = 最迟完成时间 − 最早完成时间</span></span>
<span class="line"><span>       = 最迟开始时间 − 最早开始时间</span></span></code></pre></div><p><strong>总时差为 0 的活动就是关键活动</strong>；把所有松弛时间为 0 的活动连起来，就是关键路径（也就是最长路径）。</p><p><strong>计算方法与第一课完全一样</strong>（顺推取 max 得最早时间、逆推取 min 得最迟时间），此处不重复推导，见 <a href="/ruankao/01-数据结构与算法/03-图.html">第 01 课「图」</a> 的 3.6 节关键路径四量表演算。<strong>考点在&quot;会算&quot;，不在&quot;知道名词&quot;</strong>。</p><p><strong>两种网络图记法</strong>（认名字即可）：</p><ul><li><strong>前导图法（PDM）= 单代号网络图</strong>：结点表示活动，每个结点里写 <strong>ES/EF/LS/LF</strong>（最早开始、最早完成、最迟开始、最迟完成）与总时差；<strong>正向找最大（有多条进来的路）、反向找最小（有多条出去的路）</strong>；</li><li><strong>箭线图法（ADM）= 双代号网络图</strong>：<strong>弧</strong>表示活动、结点表示事件。</li></ul><p><strong>简记</strong>：<strong>单代号看结点（活动在点上）、双代号看弧（活动在线上）</strong>。</p><h3 id="_7-2-沟通路径-两个公式-背公式-会代" tabindex="-1">7.2 沟通路径：两个公式（背公式 + 会代） <a class="header-anchor" href="#_7-2-沟通路径-两个公式-背公式-会代" aria-label="Permalink to &quot;7.2 沟通路径：两个公式（背公式 + 会代）&quot;">​</a></h3><p>n 个人协作时的沟通路径条数：</p><table tabindex="0"><thead><tr><th>情形</th><th>公式</th><th>含义</th></tr></thead><tbody><tr><td><strong>无主程序员</strong></td><td><strong>n(n−1) / 2</strong></td><td>人人都可以直接找别人，两两沟通</td></tr><tr><td><strong>有主程序员</strong></td><td><strong>n − 1</strong></td><td>所有人只跟主程序员沟通，由主程序员中转</td></tr></tbody></table><p><strong>通用形式与来源</strong>：n 个人各要联系其余 <strong>n−1</strong> 个人，共 n(n−1) 次；但每一次沟通被两端的两个人<strong>各算了一次</strong>，所以要 <strong>÷2</strong>。</p><p><strong>代入算例（n = 5）</strong>：</p><ul><li>无主：5 × 4 ÷ 2 = <strong>10 条</strong>；</li><li>有主：5 − 1 = <strong>4 条</strong>。</li></ul><p><strong>反向验算</strong>：n = 5 时，两两配对的组合数就是 C(5,2) = (5×4)/(2×1) = 10 ✓（与公式一致——n(n−1)/2 本身就是组合数公式）。</p><p><strong>口诀</strong>：<strong>无主&quot;两两配对&quot;、有主&quot;一根线串&quot;</strong>。人数一多，无主沟通量按平方增长，这正是&quot;大团队必须有主程序员/接口人&quot;的道理。</p><h3 id="_7-3-成本管理-cocomo-估算模型" tabindex="-1">7.3 成本管理：COCOMO 估算模型 <a class="header-anchor" href="#_7-3-成本管理-cocomo-估算模型" aria-label="Permalink to &quot;7.3 成本管理：COCOMO 估算模型&quot;">​</a></h3><p><strong>按代码规模（KLOC，千行）估算工作量</strong>，基本模型：</p><p><strong>E = a × (KLOC)^b</strong>，其中 <strong>E 的单位是人月</strong>。</p><p><strong>a、b 是参数</strong>，按项目类型取不同值：</p><table tabindex="0"><thead><tr><th>项目类型</th><th>特征</th></tr></thead><tbody><tr><td><strong>组织型</strong></td><td>规模小、团队熟悉领域、约束少（最&quot;宽松&quot;）</td></tr><tr><td><strong>半独立型</strong></td><td>中等规模、经验与约束都居中</td></tr><tr><td><strong>嵌入型</strong></td><td>规模大、硬件/接口/法规约束多（最&quot;苛刻&quot;）</td></tr></tbody></table><p><strong>代入算例</strong>：E = 2.0 × (KLOC)^1.0，规模 30 KLOC → <strong>E = 2.0 × 30 = 60 人月</strong>。 <strong>反向验算</strong>：60 ÷ 2.0 = 30 KLOC ✓ 自洽。</p><p><strong>考法</strong>：<strong>题干一定把公式和 a、b 都给你</strong>，考的是&quot;会不会代&quot;——别去背 a、b 的数值。</p><p>（顺带记一句：成本估算模型的规模度量有三种——<strong>对象点、功能点、代码行</strong>。COCOMO 用的是代码行。）</p><h3 id="_7-4-风险管理-四步-一个公式" tabindex="-1">7.4 风险管理：四步 + 一个公式 <a class="header-anchor" href="#_7-4-风险管理-四步-一个公式" aria-label="Permalink to &quot;7.4 风险管理：四步 + 一个公式&quot;">​</a></h3><p><strong>风险的定义</strong>：&quot;<strong>损失或伤害的可能性</strong>&quot;。</p><p><strong>风险的三类</strong>：</p><table tabindex="0"><thead><tr><th>类别</th><th>内容</th></tr></thead><tbody><tr><td><strong>项目风险</strong></td><td>预算、进度、人员等项目管理层面的风险</td></tr><tr><td><strong>技术风险</strong></td><td>技术方案、技术难度、技术选型层面的风险</td></tr><tr><td><strong>商业风险</strong></td><td>市场、产品定位、销售层面的风险</td></tr></tbody></table><p><strong>风险管理四步（背顺序）</strong>：<strong>风险识别 → 风险预测（估计概率与损失）→ 风险评估 → 风险控制</strong>。</p><p><strong>核心公式</strong>：</p><p><strong>风险暴露（风险曝光度） = 风险发生的概率 × 风险可能造成的损失</strong></p><p><strong>代入算例</strong>：某风险一旦发生会损失 10 万元，发生概率 20% → 风险暴露 = 10 × 20% = <strong>2 万元</strong>。 <strong>反向验算</strong>：2 ÷ 10 = 20% ✓ 概率算回去了。</p><p><strong>应试动作</strong>：看到&quot;概率 × 损失&quot;就是风险暴露；看到&quot;识别→预测→评估→控制&quot;就是风险管理过程。</p>`,38)])])}const q=o(g,[["render",a]]);export{u as __pageData,q as default};
